// Monta o resumo do form (parcial ou completo) + saudação e telefone do lead.
// Acesso SEGURO em tudo: num parcial as chaves de answers podem nem existir.
const CAMPOS = [["6a92da4b8490fde669082a69", "Nome"], ["6a92da4b8490fde669082a6a", "WhatsApp"], ["6a92da4b8490fde669082a6b", "Instagram"], ["6a92da4b8490fde669082a6c", "E-mail"], ["6a92da4b8490fde669082a6e", "Faturamento mensal"], ["6a92da4b8490fde669082a6d", "Ticket da mentoria"], ["6a92da4b8490fde669082a76", "Agendamentos/mês hoje"], ["6a92dcda8490fde669082a96", "Agendamentos desejados/mês"], ["6a92dc8ec7270f5d1f0c51d6", "Como gera agendamentos"], ["6a92dc7b8490fde669082a94", "O que mais frustra"], ["6a92dc16c7270f5d1f0c51d5", "Calls/mês (qualificadas)"], ["6a92dc0f7c86920578073b58", "Já rodou tráfego / investe quanto"], ["6a92dbfc7c86920578073b57", "Tem gestor de tráfego"], ["6a92da4b8490fde669082a77", "Disponível pra investir"], ["6a92da4b8490fde669082a70", "Por que agora"], ["6a92da4b8490fde669082a71", "Por que deveríamos aceitar"]];
const resp = $('Trata Webhook').item.json.response || {};
const ans = resp.answers || {};
const val = (id) => {
  const c = ans[id]?.content;
  if (c === null || c === undefined) return '';
  if (c === true) return 'Sim';
  if (c === false) return 'Não';
  return Array.isArray(c) ? c.filter(Boolean).join(', ') : String(c);
};
const linhas = CAMPOS.map(([id, rot]) => {
  const v = val(id);
  return v ? `*${rot}:* ${v}` : null;
}).filter(Boolean);
const t = resp.tracking || {};
const utm = ['utm_source','utm_campaign','utm_medium','utm_content','utm_term']
  .map(k => `${k}: ${t[k] || ''}`).join('\n');
const hora = Number(new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo', hour: '2-digit', hourCycle: 'h23',
}).format(new Date()));
const saudacao = hora < 12 ? 'Bom dia' : hora < 18 ? 'Boa tarde' : 'Boa noite';
const resumo = linhas.join('\n\n')
  + '\n\n*Origens:*\nFormulário: Agenda lotada ou não paga (yay forms)\n' + utm;
return [{ json: { ...$json, resumo, saudacao, leadPhone: val('6a92da4b8490fde669082a6a') } }];

// O form tem 3 campos Calendly (roteados por faturamento). Cada campo, quando
// agendou, devolve o link com scheduled_events/<uuid>. Detecta qual foi preenchido.
const CALENDLY = {"6a958dd13928d17403056931": "alan", "6a9825aa415d89744a050587": "cg10", "6a98254c18ff935d3e018546": "cg20"};
const ans = $('Trata Webhook').item.json.response.answers || {};
let agenda = null, link = null, eventUuid = null;
for (const [fid, nome] of Object.entries(CALENDLY)) {
  const c = ans[fid]?.content;
  if (typeof c !== 'string' || !c.includes('calendly.com')) continue;
  const m = c.match(/scheduled_events\/([0-9a-fA-F-]{36})/);
  if (!m) continue;
  agenda = nome; link = c.trim(); eventUuid = m[1];
  break;
}
return [{ json: { ...$json, agendou: !!eventUuid, agenda, calendlyLink: link, eventUuid } }];

// Formata a data/hora do evento no fuso BR ("02/09 às 14:30") e resolve o closer.
// Chave da tabela = user_name do Calendly (event_memberships[0].user_name), letra por letra.
