    "dono": "karllos.bma@gmail.com",
    "instance": "3F013E045EE7A0CFC4C76A09AA93C36C",
    "token": "B73CA8CEA2291C7EC3F5E7CA"
  },
  "Matheus Schefer BMA": {
    "closerNome": "Matheus Schefer",
    "pvPhone": "5545991195467",
    "clintUrl": "https://functions-api.clint.digital/endpoints/integration/webhook/eb9b7b9a-96c1-4aac-bac9-b12796ee7113",
    "dono": "matheusschefer.bma@gmail.com",
    "instance": "3F013E0C2FCA31C04B4FE629027F956B",
    "token": "650C95ED624C676CD5BED4E3"
  },
  "Guilherme Luiz": {
    "closerNome": "Guilherme Luiz",
    "pvPhone": "553192265968",
    "clintUrl": "https://functions-api.clint.digital/endpoints/integration/webhook/725088d1-0bea-42ed-b27c-f4adbf8eb821",
    "dono": "guilhermeluiz.bma@gmail.com",
    "instance": "3F013DFC59D5B153F35DF250B7D94EBE",
    "token": "6AF34634257C029F15126163"
  },
  "Diogo Campos": {
    "closerNome": "Diogo Campos",
    "pvPhone": "5527996120736",
    "clintUrl": "https://functions-api.clint.digital/endpoints/integration/webhook/eb4aed3e-683a-4fcc-98d8-f440a31cf905",
    "dono": "diogojaquesc@gmail.com"
  }
};
const ZAPI_BMA = "https://api.z-api.io/instances/3CFE88963A26408D365B72B70F2FFCF9/token/DA84CEA8EC9897345A31EA92/send-text";  // fallback p/ closer sem instância própria
const LABEL = { alan: 'Alan · entrevista 15min (≤20k)', cg10: 'CG10 · closers (20–50k)', cg20: 'CG20 · closers (50k+)' };
const ev = $('3 · Busca evento (por link)').item.json.resource;
const p = new Intl.DateTimeFormat('pt-BR', {
  timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit', hourCycle: 'h23',
}).formatToParts(new Date(ev.start_time));
const g = (t) => p.find((x) => x.type === t).value;
const dataHora = `${g('day')}/${g('month')} às ${g('hour')}:${g('minute')}`;
const dataHoraGrupo = `${g('day')}/${g('month')}/${g('year')} ${g('hour')}:${g('minute')}`;  // padrão dos grupos CG
// Data Aplicação p/ o Clint (padrão CG: submittedAt em yyyy-MM-dd HH:mm:ss BR); parcial com link não tem submittedAt
const resp = $('Trata Webhook').item.json.response || {};
const pa = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit',
  hour: '2-digit', minute: '2-digit', second: '2-digit', hourCycle: 'h23' }).formatToParts(new Date(resp.submittedAt || resp.createdAt || Date.now()));
const ga = (t) => pa.find((x) => x.type === t).value;
const dataAplicacao = `${ga('year')}-${ga('month')}-${ga('day')} ${ga('hour')}:${ga('minute')}:${ga('second')}`;
const agenda = $('1 · Detecta link Calendly').item.json.agenda;
