const cfg = TABELA[userName] || {};
const closerNome = agenda === 'alan' ? 'Alan Assis' : (cfg.closerNome || userName || 'closer não mapeado');
const closerFallback = agenda !== 'alan' && !cfg.instance;
const closerZapiUrl = cfg.instance
  ? `https://api.z-api.io/instances/${cfg.instance}/token/${cfg.token}/send-text`
  : ZAPI_BMA;
const agendaLabel = (LABEL[agenda] || agenda || '?') + (agenda === 'alan' ? '' : ` · ${closerNome}`)
  + (closerFallback ? ' ⚠️ closer sem instância Z-API (msgs pela instância BMA)' : '');
return [{ json: { ...$json, evento: ev, dataHora, dataHoraGrupo, dataAplicacao, agenda,
  clintUrl: cfg.clintUrl || '', dono: cfg.dono || '', agendaLabel, closerNome,
  closerPv: cfg.pvPhone || '', closerZapiUrl, closerFallback, _closerUserName: userName } }];

